<script setup lang="ts">
import dayjs from 'dayjs';import{toast}from'vue-sonner';import{z}from'zod';import type{Pks}from'~/types'
const auth=useAuthStore();const{db,seed,audit}=useDatabase();const rows=ref<Pks[]>([]);const search=ref('');const show=ref(false);const editing=ref<number>();const form=reactive({idpks:'',nama:'',pic:'',handphone:'',alamat:'',status:'Aktif' as 'Aktif'|'Nonaktif'})
const filtered=computed(()=>rows.value.filter(row=>`${row.idpks} ${row.nama} ${row.pic} ${row.handphone}`.toLowerCase().includes(search.value.toLowerCase())));const permission=computed(()=>auth.user?.permissions.pks);const isSuperadmin=computed(()=>auth.user?.role==='superadmin');const canCreate=computed(()=>(isSuperadmin.value||auth.user?.role==='admin')&&(isSuperadmin.value||permission.value?.create));const canUpdate=computed(()=>isSuperadmin.value||permission.value?.update);const canDelete=computed(()=>isSuperadmin.value||permission.value?.delete)
async function load(){await seed();const data=await db.pks.toArray();for(const row of data)if(!row.status){row.status='Aktif';await db.pks.update(row.id!,{status:'Aktif'})}rows.value=data}
function open(row?:Pks){if(row&&!canUpdate.value)return toast.error('Anda tidak memiliki izin update PKS');if(!row&&!canCreate.value)return toast.error('Create PKS hanya untuk admin atau superadmin dengan izin RLS');editing.value=row?.id;Object.assign(form,row?{idpks:row.idpks,nama:row.nama,pic:row.pic,handphone:row.handphone,alamat:row.alamat,status:row.status}:{idpks:crypto.randomUUID(),nama:'',pic:'',handphone:'',alamat:'',status:'Aktif'});show.value=true}
async function save(){const result=z.object({idpks:z.uuid(),nama:z.string().min(3,'Nama minimal 3 karakter'),pic:z.string().min(3,'PIC minimal 3 karakter'),handphone:z.string().min(8,'Handphone minimal 8 digit').regex(/^[0-9+ -]+$/,'Format handphone tidak valid'),alamat:z.string().min(5,'Alamat minimal 5 karakter'),status:z.enum(['Aktif','Nonaktif'])}).safeParse(form);if(!result.success)return toast.error(result.error.issues[0]?.message??'Data tidak valid');const actor=auth.user?.email||'system';const now=dayjs().toISOString();if(editing.value){const old=await db.pks.get(editing.value);await db.pks.update(editing.value,{...result.data,createdBy:old!.createdBy,createdAt:old!.createdAt,updatedBy:actor,updatedAt:now})}else await db.pks.add({...result.data,createdBy:actor,createdAt:now});await audit(editing.value?'UPDATE':'CREATE','PKS',`${form.idpks} - ${form.nama}`);show.value=false;toast.success('Data PKS berhasil disimpan');await load()}
async function remove(row:Pks){if(!canDelete.value)return toast.error('Anda tidak memiliki izin delete PKS');if(!confirm(`Hapus ${row.nama}?`))return;await db.pks.delete(row.id!);await audit('DELETE','PKS',`${row.idpks} - ${row.nama}`);toast.success('Data PKS dihapus');await load()}onMounted(load)
</script>
<template><div><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><h2 class="text-2xl font-bold">Data PKS</h2><p class="text-sm text-slate-500">Kelola data Pabrik Kelapa Sawit.</p></div><button v-if="canCreate" class="btn-primary" @click="open()">＋ PKS</button></div><div class="card overflow-hidden"><div class="border-b p-4"><input v-model="search" class="input max-w-sm" placeholder="Cari nama, PIC, atau handphone..."></div><div class="overflow-x-auto"><table class="min-w-[1250px] w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-400"><tr><th v-for="h in ['No','Nama','PIC','Handphone','Alamat','Status','Aksi']" :key="h" class="px-5 py-3">{{h}}</th></tr></thead><tbody><tr v-for="(row, idx) in filtered" :key="row.id" class="border-t align-top hover:bg-slate-50"><td class="max-w-52 break-all px-5 py-4 font-mono text-xs text-ocean-600">{{idx + 1}}</td><td class="px-5 py-4 font-semibold">{{row.nama}}</td><td class="px-5 py-4">{{row.pic}}</td><td class="px-5 py-4">{{row.handphone}}</td><td class="max-w-64 px-5 py-4 text-slate-500">{{row.alamat}}</td><td class="px-5 py-4"><span :class="row.status==='Aktif'?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'" class="rounded-full px-2.5 py-1 text-xs font-semibold">{{row.status}}</span></td><td class="px-5 py-4"><div class="mb-3 whitespace-nowrap text-xs text-slate-400"><p><b class="text-slate-500">Created:</b> {{row.createdBy}}</p><p>{{dayjs(row.createdAt).format('DD/MM/YYYY HH:mm:ss')}}</p><template v-if="row.updatedAt"><p class="mt-2"><b class="text-slate-500">Updated:</b> {{row.updatedBy}}</p><p>{{dayjs(row.updatedAt).format('DD/MM/YYYY HH:mm:ss')}}</p></template></div><div class="flex gap-3"><button v-if="canUpdate" class="font-medium text-ocean-600" @click="open(row)">Update</button><button v-if="canDelete" class="font-medium text-red-500" @click="remove(row)">Delete</button><span v-if="!canUpdate&&!canDelete" class="text-xs text-slate-400">Hanya lihat</span></div></td></tr><tr v-if="!filtered.length"><td colspan="7" class="p-10 text-center text-slate-400">Belum ada data PKS</td></tr></tbody></table></div></div><div v-if="show" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4" @click.self="show=false"><form class="card w-full max-w-2xl p-6" @submit.prevent="save"><h3 class="mb-5 text-xl font-bold">{{editing?'Update':'Tambah'}} PKS</h3><div class="grid gap-4 sm:grid-cols-2"><input type="hidden" v-model="form.idpks"><div><label class="label">Nama</label><input v-model="form.nama" class="input"></div><div><label class="label">PIC</label><input v-model="form.pic" class="input"></div><div><label class="label">Handphone</label><input v-model="form.handphone" class="input" inputmode="tel"></div><div><label class="label">Status</label><select v-model="form.status" class="input"><option>Aktif</option><option>Nonaktif</option></select></div><div class="sm:col-span-2"><label class="label">Alamat</label><textarea v-model="form.alamat" class="input" rows="3"></textarea></div></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="btn-secondary" @click="show=false">Batal</button><button class="btn-primary">{{editing?'Update':'Simpan'}}</button></div></form></div></div></template>
